# Annotations: flows, flow properties, energy, transformation, signal.
from ann_refs import *
from ann_functions import ANN, A

# ---------------------------------------------------------------- flows
A("Flow",
  nld_pt="processo em que alguma entidade material atravessa uma interface de um artefato ou sistema de engenharia, carregando consigo algum material, energia ou conteúdo de informação",
  sfd_en="if x is a 'flow' then x is a 'process' that 'has participant' some 'material entity' and that is the crossing of one interface of an artifact or engineered system by that participant",
  sfd_pt="se x é um 'fluxo' então x é um 'processo' que 'tem participante' alguma 'entidade material' e que é o atravessar de uma interface de um artefato ou sistema de engenharia por esse participante",
  fol="∀x (Flow(x) → Process(x) ∧ ∃m (MaterialEntity(m) ∧ hasParticipant(x,m)))",
  ex_en="The suction of a pump (liquid crossing the suction nozzle); the shaft power entering a compressor (energy transfer across the coupling); the 4–20 mA signal leaving a transmitter.",
  ex_pt="A sucção de uma bomba (líquido atravessando o bocal de sucção); a potência de eixo entrando num compressor (transferência de energia através do acoplamento); o sinal de 4–20 mA saindo de um transmissor.",
  note_pt="Um fluxo por interface atravessada. O que acontece dentro do artefato (transformação, mistura, separação) não é fluxo, mas outra parte ocorrente do processo que realiza a função. O mesmo fluxo pode ser fluxo de saída do processo de um artefato e fluxo de entrada do seguinte: é o atravessar da interface que compartilham. A Functional Basis deixa em aberto se o fluxo é o operando ou sua mudança no tempo; a COPI adota a leitura ocorrente pelas razões registradas no ODR-024 (energia e sinal não são operandos; a direção é relacional e temporal; é o que a formalização de referência fez).",
  rat_en="Primitive: 'crossing one interface' presupposes the interface (a fiat boundary or site of the artifact) which this version keeps implicit; the class is characterized by its participant and by the direction properties, not defined.",
  rat_pt="Primitiva: 'atravessar uma interface' pressupõe a interface (uma fronteira fiat ou sítio do artefato) que esta versão deixa implícita; a classe é caracterizada pelo participante e pelas propriedades de direção, não definida.",
  sources=["ODR-024 §4 and §1.1.1 of the spec", HIRTZ_T3, STONE, BORGO, VERMAAS, BFO], adapted=STONE + " (flow as 'a change in material, energy or signal with respect to time'); " + BORGO)
A("MaterialFlow",
  nld_pt="fluxo cujo participante é uma porção de fluido, uma porção de sólido ou um objeto: o próprio material é o que atravessa a interface",
  sfd_en="if x is a 'material flow' then x is a 'flow' that 'has participant' some 'portion of fluid', 'portion of solid' or 'object'",
  sfd_pt="se x é um 'fluxo de material' então x é um 'fluxo' que 'tem participante' alguma 'porção de fluido', 'porção de sólido' ou 'objeto'",
  fol="∀x (MaterialFlow(x) → Flow(x) ∧ ∃m ((PortionOfFluid(m) ∨ PortionOfSolid(m) ∨ Object(m)) ∧ hasParticipant(x,m)))",
  ex_en="Crude oil entering a separator; cuttings leaving a shale shaker; a pig entering a pig launcher (object).",
  ex_pt="Óleo cru entrando num separador; cascalho saindo de uma peneira vibratória; um pig entrando num lançador de pigs (objeto).",
  note_pt="Uma corrente de processo (Stream do OntoCAPE, da ISO 15926, do CFIHOS) é um fluxo de material em regime permanente numa dada interface. Não é disjunto de fluxo de energia nem de fluxo de sinal: um líquido pressurizado escoando é fluxo de material e de energia (carrier flow).",
  rat_en="Primitive: the participant restriction is necessary but not sufficient (an energy flow may have the same participant as its bearer).",
  rat_pt="Primitiva: a restrição de participante é necessária mas não suficiente (um fluxo de energia pode ter o mesmo participante como portador).",
  sources=["ODR-024 §4", "ODR-010 §2 (portions)", HIRTZ_T3, ONTOCAPE, ISO15926], adapted=HIRTZ_T3 + " (material: human, gas, liquid, solid, plasma, mixture)")
A("EnergyFlow",
  nld_pt="fluxo que é uma transferência de energia através da interface: um decréscimo de alguma qualidade de energia no portador de um lado, causalmente relacionado a um acréscimo de uma qualidade de energia do mesmo tipo no portador do outro lado",
  sfd_en="if x is an 'energy flow' then x is a 'flow' that 'has occurrent part' some 'energy decrease' and 'has occurrent part' some 'energy increase'",
  sfd_pt="se x é um 'fluxo de energia' então x é um 'fluxo' que 'tem parte ocorrente' algum 'decréscimo de energia' e 'tem parte ocorrente' algum 'acréscimo de energia'",
  fol="∀x (EnergyFlow(x) → Flow(x) ∧ ∃d (EnergyDecrease(d) ∧ hasOccurrentPart(x,d)) ∧ ∃i (EnergyIncrease(i) ∧ hasOccurrentPart(x,i)))",
  ex_en="Shaft power from a motor into a pump (mechanical energy); heat from a hot stream into a cold one across a tube wall (thermal energy); current through a cable into a motor (electrical energy).",
  ex_pt="Potência de eixo de um motor para uma bomba (energia mecânica); calor de uma corrente quente para uma fria através da parede do tubo (energia térmica); corrente por um cabo para um motor (energia elétrica).",
  note_pt="Transformação de energia (tipos diferentes, mesmo portador) não é fluxo; ver transformação de energia. Não se declara a restrição de participante 'portador de alguma energia' porque toda entidade material a satisfaz; o que distingue um fluxo de energia são suas partes de decréscimo/acréscimo. Segue o padrão de transferência de energia do MENO: a qualidade de energia nunca migra entre portadores.",
  rat_en="Primitive: the decrease/increase parts are necessary; sufficiency would require stating that the two parts are causally related across the interface, which BFO/RO express only on instances (causally related to).",
  rat_pt="Primitiva: as partes de decréscimo/acréscimo são necessárias; a suficiência exigiria afirmar que as duas partes são causalmente relacionadas através da interface, o que BFO/RO só expressam sobre instâncias (causalmente relacionado a).",
  sources=["ODR-024 §4–5", "ODR-010 §1 and §5 (superseded)", MENO, RO, HIRTZ_T3], adapted=MENO + ": energy transfer (MENO_01002)")
A("SignalFlow",
  nld_pt="fluxo que concretiza uma entidade de conteúdo de informação, diretamente (o BFO 2020 admite um processo como concretizador) ou por meio de uma qualidade do seu portador de sinal, e a transmite entre artefatos",
  sfd_en="if x is a 'signal flow' then x is a 'flow' that either 'concretizes' some 'information content entity' or 'has participant' some 'signal bearer' that is 'bearer of' some quality that 'concretizes' some 'information content entity'",
  sfd_pt="se x é um 'fluxo de sinal' então x é um 'fluxo' que ou 'concretiza' alguma 'entidade de conteúdo de informação' ou 'tem participante' algum 'portador de sinal' que é 'portador de' alguma qualidade que 'concretiza' alguma 'entidade de conteúdo de informação'",
  fol="∀x (SignalFlow(x) → Flow(x) ∧ (∃c (InformationContentEntity(c) ∧ concretizes(x,c)) ∨ ∃b (SignalBearer(b) ∧ hasParticipant(x,b) ∧ ∃q (bearerOf(b,q) ∧ ∃c (InformationContentEntity(c) ∧ concretizes(q,c))))))",
  ex_en="The 4–20 mA output of a pressure transmitter (measurement content); the setpoint reaching a control valve positioner (control content); a high-level alarm reaching the control room (status content).",
  ex_pt="A saída de 4–20 mA de um transmissor de pressão (conteúdo de medição); o setpoint chegando ao posicionador de uma válvula de controle (conteúdo de controle); um alarme de nível alto chegando à sala de controle (conteúdo de estado).",
  note_pt="A forma curta (o fluxo concretiza o conteúdo) responde se há sinal; a forma longa (uma qualidade do portador o concretiza) responde por qual portador passou. Para um loop de 4–20 mA a corrente é um concretizador natural; para Modbus/OPC o processo é o concretizador honesto. O mesmo fluxo de sinal é saída do transmissor e entrada do controlador (CQ28).",
  rat_en="Primitive: the disjunction is necessary; it is not sufficient because a material flow may also carry information content (a sample), and whether that counts as a signal is a design decision.",
  rat_pt="Primitiva: a disjunção é necessária; não é suficiente porque um fluxo de material também pode carregar conteúdo de informação (uma amostra), e se isso conta como sinal é decisão de projeto.",
  sources=["ODR-024 §4 and §6", "ODR-023 (reading A)", BFO + " — concretizes (BFO_0000059): domain process or specifically dependent continuant", IAO, ISA51], adapted=IAO)

# ---------------------------------------------------------------- flow properties (object properties)
A("hasInflow",
  nld_pt="fluxo, parte ocorrente do processo que realiza uma função, que atravessa uma interface do portador para dentro",
  sfd_en="if p 'has inflow' x then x is a 'flow' that is an 'occurrent part' of the process p and that crosses an interface of the bearer of the function p realizes, inwards",
  sfd_pt="se p 'tem fluxo de entrada' x então x é um 'fluxo' que é 'parte ocorrente' do processo p e que atravessa uma interface do portador da função que p realiza, para dentro",
  fol="∀p,x (hasInflow(p,x) → Process(p) ∧ Flow(x) ∧ hasOccurrentPart(p,x))",
  ex_en="The pumping process of a pump has as inflow the liquid crossing the suction nozzle and the mechanical energy crossing the coupling.",
  ex_pt="O processo de bombeamento de uma bomba tem como fluxo de entrada o líquido que atravessa o bocal de sucção e a energia mecânica que atravessa o acoplamento.",
  note_pt="A direção é relativa à fronteira do artefato cuja função o processo realiza: 'entra' e 'sai' são predicados de um ocorrente delimitado pela interface, não de uma porção. Subpropriedade de 'tem parte ocorrente' (BFO_0000117).",
  sources=["ODR-024 §4", BFO], adapted=HIRTZ + " (input flows of a function)")
A("hasOutflow",
  nld_pt="fluxo, parte ocorrente do processo que realiza uma função, que atravessa uma interface do portador para fora",
  sfd_en="if p 'has outflow' x then x is a 'flow' that is an 'occurrent part' of the process p and that crosses an interface of the bearer of the function p realizes, outwards",
  sfd_pt="se p 'tem fluxo de saída' x então x é um 'fluxo' que é 'parte ocorrente' do processo p e que atravessa uma interface do portador da função que p realiza, para fora",
  fol="∀p,x (hasOutflow(p,x) → Process(p) ∧ Flow(x) ∧ hasOccurrentPart(p,x))",
  ex_en="The pumping process of a pump has as outflow the pressurized liquid crossing the discharge nozzle (a material flow and an energy flow).",
  ex_pt="O processo de bombeamento de uma bomba tem como fluxo de saída o líquido pressurizado que atravessa o bocal de descarga (fluxo de material e de energia).",
  note_pt="Ver 'tem fluxo de entrada'. O mesmo fluxo é fluxo de saída de um artefato e fluxo de entrada do seguinte (individuação por interface).",
  sources=["ODR-024 §4", BFO], adapted=HIRTZ + " (output flows of a function)")
A("hasInflowParticipant",
  nld_en="relation between a process that realizes a function and a continuant that participates in one of its inflows: the operand, or its bearer, that enters the artifact",
  nld_pt="relação entre um processo que realiza uma função e um continuante que participa de um de seus fluxos de entrada: o operando, ou seu portador, que entra no artefato",
  sfd_en="if p 'has inflow participant' c then p 'has inflow' some flow x such that x 'has participant' c",
  sfd_pt="se p 'tem participante de fluxo de entrada' c então p 'tem fluxo de entrada' algum fluxo x tal que x 'tem participante' c",
  fol="∀p,c (hasInflowParticipant(p,c) ↔ ∃x (hasInflow(p,x) ∧ hasParticipant(x,c)))",
  ex_en="The pumping process has as inflow participant the portion of liquid at suction conditions — what ODR-010 called the input.",
  ex_pt="O processo de bombeamento tem como participante de fluxo de entrada a porção de líquido nas condições de sucção — o que o ODR-010 chamava de entrada.",
  note_pt="Cadeia 'tem fluxo de entrada' ∘ 'tem participante'. Declarada como propriedade própria da COPI porque a cadeia que termina em iof:hasInput não é regular em OWL 2 DL dado hasInput ⊑ has participant (IOF Core 202603); pelo mesmo motivo esta propriedade NÃO é declarada subpropriedade de 'tem participante' (fecharia o ciclo, como o HermiT reporta). O export materializa iof:hasInput e 'tem participante' a partir dela por SPARQL CONSTRUCT.",
  sources=["ODR-024 §7", IOF, BFO], adapted=IOF + ": hasInput (related match)")
A("hasOutflowParticipant",
  nld_en="relation between a process that realizes a function and a continuant that participates in one of its outflows: the operand, or its bearer, that leaves the artifact",
  nld_pt="relação entre um processo que realiza uma função e um continuante que participa de um de seus fluxos de saída: o operando, ou seu portador, que sai do artefato",
  sfd_en="if p 'has outflow participant' c then p 'has outflow' some flow x such that x 'has participant' c",
  sfd_pt="se p 'tem participante de fluxo de saída' c então p 'tem fluxo de saída' algum fluxo x tal que x 'tem participante' c",
  fol="∀p,c (hasOutflowParticipant(p,c) ↔ ∃x (hasOutflow(p,x) ∧ hasParticipant(x,c)))",
  ex_en="The pumping process has as outflow participant the portion of liquid at discharge conditions.",
  ex_pt="O processo de bombeamento tem como participante de fluxo de saída a porção de líquido nas condições de descarga.",
  note_pt="Ver 'tem participante de fluxo de entrada'; mesma cadeia e mesma razão para não ser subpropriedade de 'tem participante'.",
  sources=["ODR-024 §7", IOF, BFO], adapted=IOF + ": hasOutput (related match)")

# ---------------------------------------------------------------- energy
A("Energy",
  nld_pt="qualidade de uma entidade material cuja magnitude pode decrescer no seu portador enquanto uma qualidade causalmente relacionada do mesmo tipo cresce em outro portador (transferência), ou enquanto uma qualidade de tipo diferente cresce no mesmo portador (transformação)",
  sfd_en="if q is an 'energy' then q is a 'quality' that 'inheres in' some 'material entity'",
  sfd_pt="se q é uma 'energia' então q é uma 'qualidade' que 'inere em' alguma 'entidade material'",
  fol="∀q (Energy(q) → Quality(q) ∧ ∃m (MaterialEntity(m) ∧ inheresIn(q,m)))",
  ex_en="The kinetic energy of a rotating shaft; the thermal energy of a hot stream; the electrical energy of a charged cable.",
  ex_pt="A energia cinética de um eixo girante; a energia térmica de uma corrente quente; a energia elétrica de um cabo energizado.",
  note_pt="Como continuante especificamente dependente, uma qualidade de energia nunca migra entre portadores; 'transferência' é o par decréscimo-aqui/acréscimo-ali (MENO). A redação anterior 'pode ser transferida a outra entidade material' afirmava o que o padrão de processo existe para evitar. Os tipos seguem a taxonomia de fluxos da Functional Basis usada na cobertura COPI; o MENO é alinhado, não importado (IRIs são URLs raw do GitHub, importa BFO 2.0, e não tem energia mecânica, hidráulica nem pneumática).",
  rat_en="Primitive: energy is characterized by what its decrease and increase do (transfer, transformation), not defined; MENO and OEO keep it primitive as well.",
  rat_pt="Primitiva: a energia é caracterizada pelo que seu decréscimo e acréscimo fazem (transferência, transformação), não definida; MENO e OEO também a mantêm primitiva.",
  sources=["ODR-024 §5", "ODR-010 §1 (superseded)", MENO, OEO, BFO], adapted=MENO + ": energy ⊑ bfo:quality, quality of some material entity (MENO_01001)")
_EN = {
 "MechanicalEnergy": ("energia mecânica como tipo de qualidade de energia do seu portador, no sentido da taxonomia de fluxos da Functional Basis: energia cinética mais potencial de um corpo ou eixo",
   "The energy of the shaft of a motor or a turbine; of a moving pig; of a pressurized spring in an actuator.",
   "A energia do eixo de um motor ou de uma turbina; de um pig em movimento; de uma mola comprimida num atuador.",
   "energia cinética mais potencial de um corpo ou eixo; mais ampla que a energia cinética do MENO (relatedMatch, não closeMatch). Na Functional Basis: rotacional, translacional, vibracional, pneumática e hidráulica são subtipos; a COPI separa as duas últimas pelo portador."),
 "HydraulicEnergy": ("energia hidráulica como tipo de qualidade de energia do seu portador: energia de pressão-volume de um líquido",
   "The energy of the liquid at the discharge of a pump; of the hydraulic fluid in a BOP accumulator; of the control oil of a hydraulic actuator.",
   "A energia do líquido na descarga de uma bomba; do fluido hidráulico num acumulador de BOP; do óleo de comando de um atuador hidráulico.",
   "tipo baseado no portador, da Functional Basis: energia de pressão-volume de um líquido; uma distinção de engenharia pelo portador, não um tipo físico. Sem correspondente no MENO."),
 "PneumaticEnergy": ("energia pneumática como tipo de qualidade de energia do seu portador: energia de pressão-volume de um gás",
   "The energy of the gas at the discharge of a compressor; of the instrument air driving a pneumatic actuator; of the gas in a surge vessel.",
   "A energia do gás na descarga de um compressor; do ar de instrumento que aciona um atuador pneumático; do gás num vaso pulmão.",
   "como a energia hidráulica, para um gás. Sem correspondente no MENO."),
 "ThermalEnergy": ("energia térmica como tipo de qualidade de energia do seu portador",
   "The energy of a hot process stream; of a heating medium; of the flue gas of a furnace.",
   "A energia de uma corrente de processo quente; de um meio de aquecimento; do gás de combustão de um forno.",
   "transferida entre portadores por um trocador de calor; closeMatch com a energia térmica do MENO."),
 "ElectricalEnergy": ("energia elétrica como tipo de qualidade de energia do seu portador",
   "The energy of the supply cable of a motor; of the bus bar of a switchboard; of a battery.",
   "A energia do cabo de alimentação de um motor; do barramento de um painel; de uma bateria.",
   "transferida por cabos e barramentos; convertida por motores, geradores e transformadores (estes últimos mudam a magnitude, não o tipo)."),
 "ChemicalEnergy": ("energia química como tipo de qualidade de energia do seu portador",
   "The energy of the fuel gas of a turbine; of the crude oil in a tank; of the reagents of a reactor.",
   "A energia do gás combustível de uma turbina; do óleo cru num tanque; dos reagentes de um reator.",
   "convertida em térmica por combustão e em elétrica por células a combustível."),
 "ElectromagneticEnergy": ("energia eletromagnética como tipo de qualidade de energia do seu portador",
   "The energy of the radiation of a flame seen by a flame detector; of the field of a transformer core; of a radio link.",
   "A energia da radiação de uma chama vista por um detector de chama; do campo do núcleo de um transformador; de um enlace de rádio.",
   "energia radiativa no MENO (relatedMatch); na Functional Basis cobre óptica, solar e magnética."),
}
for k,(nld_pt,ex_en,ex_pt,note_pt) in _EN.items():
    A(k, nld_pt=nld_pt, ex_en=ex_en, ex_pt=ex_pt, note_pt=note_pt,
      sfd_en=f"if q is a '{k.replace('Energy',' energy').lower().strip()}' then q is an 'energy'",
      sfd_pt="se q é uma energia deste tipo então q é uma 'energia'", fol=f"∀q ({k}(q) → Energy(q))",
      rat_en="Primitive: the kinds of energy are the Functional Basis flow taxonomy, distinguished by physics or by bearer in natural language; they are not declared disjoint (hydraulic energy is mechanical energy of a liquid).",
      rat_pt="Primitiva: os tipos de energia são a taxonomia de fluxos da Functional Basis, distinguidos pela física ou pelo portador em linguagem natural; não são declarados disjuntos (energia hidráulica é energia mecânica de um líquido).",
      sources=["ODR-024 §5", HIRTZ_T3, MENO], adapted=HIRTZ_T3 + " (energy: human, acoustic, biological, chemical, electrical, electromagnetic, hydraulic, magnetic, mechanical, pneumatic, radioactive, thermal)")
A("EnergyDecrease",
  nld_pt="processo que regula negativamente uma qualidade de energia do seu portador",
  sfd_en="if d is an 'energy decrease' then d is a 'process' that 'negatively regulates characteristic' some 'energy'",
  sfd_pt="se d é um 'decréscimo de energia' então d é um 'processo' que 'regula negativamente a característica' alguma 'energia'",
  fol="∀d (EnergyDecrease(d) → Process(d) ∧ ∃q (Energy(q) ∧ negativelyRegulatesCharacteristic(d,q)))",
  ex_en="The decrease of thermal energy of the hot stream in an exchanger; the decrease of mechanical energy of the motor shaft as it drives the pump.",
  ex_pt="O decréscimo de energia térmica da corrente quente num trocador; o decréscimo de energia mecânica do eixo do motor ao acionar a bomba.",
  note_pt="Metade do padrão de transferência/transformação do MENO: um decréscimo aqui, causalmente relacionado a um acréscimo ali (transferência) ou de outro tipo no mesmo portador (transformação). Usa as propriedades de regulação de característica do RO.",
  rat_en="Primitive: a process characterized by its effect on a quality; RO's regulates-characteristic relations are themselves primitive.",
  rat_pt="Primitiva: um processo caracterizado pelo seu efeito sobre uma qualidade; as relações de regulação de característica do RO são elas mesmas primitivas.",
  sources=["ODR-024 §5", MENO, RO], adapted=MENO + ": energy decrease (MENO_01013)")
A("EnergyIncrease",
  nld_pt="processo que regula positivamente uma qualidade de energia do seu portador",
  sfd_en="if i is an 'energy increase' then i is a 'process' that 'positively regulates characteristic' some 'energy'",
  sfd_pt="se i é um 'acréscimo de energia' então i é um 'processo' que 'regula positivamente a característica' alguma 'energia'",
  fol="∀i (EnergyIncrease(i) → Process(i) ∧ ∃q (Energy(q) ∧ positivelyRegulatesCharacteristic(i,q)))",
  ex_en="The increase of hydraulic energy of the liquid through a pump; the increase of thermal energy of the cold stream in an exchanger.",
  ex_pt="O acréscimo de energia hidráulica do líquido através de uma bomba; o acréscimo de energia térmica da corrente fria num trocador.",
  note_pt="Ver decréscimo de energia.",
  rat_en="Primitive: see energy decrease.", rat_pt="Primitiva: ver decréscimo de energia.",
  sources=["ODR-024 §5", MENO, RO], adapted=MENO + ": energy increase (MENO_01014)")
A("Transformation",
  nld_pt="processo, parte ocorrente da realização de uma função de conversão, em que a forma do operando muda dentro do artefato: o tipo de energia portada, a fase, ou a composição química",
  sfd_en="if t is a 'transformation' then t is a 'process' that is an 'occurrent part' of some process realizing a 'conversion function' and that does not cross an interface of the bearer",
  sfd_pt="se t é uma 'transformação' então t é um 'processo' que é 'parte ocorrente' de algum processo que realiza uma 'função de conversão' e que não atravessa uma interface do portador",
  fol="∀t (Transformation(t) → Process(t))",
  ex_en="Mechanical → hydraulic energy inside a pump; electrical → mechanical inside a motor; liquid → vapour inside a reboiler.",
  ex_pt="Energia mecânica → hidráulica dentro de uma bomba; elétrica → mecânica dentro de um motor; líquido → vapor dentro de um refervedor.",
  note_pt="Não atravessa interface; portanto não é fluxo. É a marca formal da função de conversão, que de outro modo seria indistinguível de canalizar/transferir. 'Converter' da Functional Basis muda a forma do fluxo; a COPI localiza a mudança dentro do artefato e deixa as interfaces para os fluxos.",
  rat_en="Primitive: 'the form of the operand changes' is what its two subclasses specify; the class is the common part.",
  rat_pt="Primitiva: 'a forma do operando muda' é o que suas duas subclasses especificam; a classe é a parte comum.",
  sources=["ODR-024 §5", HIRTZ_T5 + " — 'Convert'", MENO], adapted=HIRTZ + " ('Convert': to change from one form of a flow to another)")
A("EnergyTransformation",
  nld_pt="transformação em que uma qualidade de energia de um tipo decresce e, causalmente relacionada, uma qualidade de energia de tipo diferente cresce no mesmo portador",
  sfd_en="if t is an 'energy transformation' then t is a 'transformation' that 'has occurrent part' some 'energy decrease' and 'has occurrent part' some 'energy increase', regulating energy qualities of different kinds of the same bearer",
  sfd_pt="se t é uma 'transformação de energia' então t é uma 'transformação' que 'tem parte ocorrente' algum 'decréscimo de energia' e 'tem parte ocorrente' algum 'acréscimo de energia', regulando qualidades de energia de tipos diferentes do mesmo portador",
  fol="∀t (EnergyTransformation(t) → Transformation(t) ∧ ∃d (EnergyDecrease(d) ∧ hasOccurrentPart(t,d)) ∧ ∃i (EnergyIncrease(i) ∧ hasOccurrentPart(t,i)))",
  ex_en="Electrical → mechanical in a motor; mechanical → electrical in a generator; chemical → thermal in a burner; mechanical → hydraulic in a pump.",
  ex_pt="Elétrica → mecânica num motor; mecânica → elétrica num gerador; química → térmica num queimador; mecânica → hidráulica numa bomba.",
  note_pt="O decréscimo e o acréscimo regulam qualidades de energia de tipos DIFERENTES inerentes ao MESMO portador; o decréscimo é causalmente relacionado ao acréscimo (RO_0002410). Distingue-se da transferência (mesmo tipo, dois portadores), que é fluxo de energia. Um transformador elétrico não transforma: muda a magnitude (tensão) do mesmo tipo de energia — é controle de magnitude/mudar.",
  rat_en="Primitive: 'different kinds in the same bearer' is not expressible in OWL 2 DL without variables shared across restrictions; it is stated in natural language and in the FOL.",
  rat_pt="Primitiva: 'tipos diferentes no mesmo portador' não é exprimível em OWL 2 DL sem variáveis compartilhadas entre restrições; é dito em linguagem natural e na FOL.",
  sources=["ODR-024 §5", MENO, RO], adapted=MENO + ": energy transformation (MENO_01003)")
A("MaterialTransformation",
  nld_pt="transformação em que a fase ou a composição química do operando material muda dentro do artefato",
  sfd_en="if t is a 'material transformation' then t is a 'transformation' of the phase or of the chemical composition of a material operand",
  sfd_pt="se t é uma 'transformação de material' então t é uma 'transformação' da fase ou da composição química de um operando material",
  fol="∀t (MaterialTransformation(t) → Transformation(t))",
  ex_en="Vaporization in a reboiler; condensation in a condenser; hydrodesulphurization in a reactor.",
  ex_pt="Vaporização num refervedor; condensação num condensador; hidrodessulfurização num reator.",
  note_pt="É a parte interna da realização das funções de mudança de fase e de reação química (ODR-025 §4). Detalhar com as porções e qualidades do ODR-010 §2 quando as CQs exigirem fase e composição como qualidades.",
  rat_en="Primitive: phase and composition are qualities of the operand that COPI does not yet model; the class is placed by its parent.",
  rat_pt="Primitiva: fase e composição são qualidades do operando que a COPI ainda não modela; a classe é posicionada pelo pai.",
  sources=["ODR-024 §5", "ODR-010 §2", MCCABE], adapted=MCCABE)

# ---------------------------------------------------------------- signal
A("SignalBearer",
  nld_pt="entidade material (um loop de corrente, um cabo, uma linha pneumática, um segmento de rede) alguma qualidade da qual, ou algum fluxo de sinal através da qual, concretiza uma entidade de conteúdo de informação transmitida entre artefatos",
  sfd_en="if b is a 'signal bearer' then b is a 'material entity' that is 'bearer of' some quality, or participant of some 'signal flow', that 'concretizes' some 'information content entity'",
  sfd_pt="se b é um 'portador de sinal' então b é uma 'entidade material' que é 'portadora de' alguma qualidade, ou participante de algum 'fluxo de sinal', que 'concretiza' alguma 'entidade de conteúdo de informação'",
  fol="∀b (SignalBearer(b) → MaterialEntity(b))",
  ex_en="A 4–20 mA current loop; an instrument air line to a pneumatic positioner; a fieldbus segment; a fibre-optic cable.",
  ex_pt="Um loop de corrente de 4–20 mA; uma linha de ar de instrumento até um posicionador pneumático; um segmento de fieldbus; um cabo de fibra óptica.",
  note_pt="O IOF Core 202603 não tem classe de portador de informação; esta é da COPI. O portador responde 'por qual cabo'; o conteúdo responde 'sobre o quê'. Adaptado do portador material de informação do IAO e da entidade portadora de informação do CCO.",
  rat_en="Primitive: 'some quality of which concretizes' is a role-like characterization; a sufficient condition would make every cable a signal bearer whenever it is energized.",
  rat_pt="Primitiva: 'alguma qualidade da qual concretiza' é uma caracterização de tipo papel; uma condição suficiente faria de todo cabo um portador de sinal sempre que energizado.",
  sources=["ODR-024 §6", IAO, IOF, BFO], adapted=IAO)
A("MeasurementContent",
  nld_pt="entidade de conteúdo de informação descritiva, produzida por sensoriamento contínuo, que descreve uma qualidade da entidade observada e tem uma expressão de valor medido",
  sfd_en="if c is a 'measurement content' then c is a 'descriptive information content entity' that 'describes' some 'quality' and 'has value expression at all times' some 'measured value expression'",
  sfd_pt="se c é um 'conteúdo de medição' então c é uma 'entidade de conteúdo de informação descritiva' que 'descreve' alguma 'qualidade' e 'tem expressão de valor em todos os tempos' alguma 'expressão de valor medido'",
  fol="∀c (MeasurementContent(c) → DescriptiveInformationContentEntity(c) ∧ ∃q (Quality(q) ∧ describes(c,q)) ∧ ∃v (MeasuredValueExpression(v) ∧ hasValueExpressionAtAllTimes(c,v)))",
  ex_en="The pressure value carried by a transmitter's output; the temperature value of a thermocouple loop; the flow rate shown by a flow computer.",
  ex_pt="O valor de pressão carregado pela saída de um transmissor; o valor de temperatura de um loop de termopar; a vazão mostrada por um computador de vazão.",
  note_pt="Irmã, não equivalente, de iof:MeasurementInformationContentEntity: a classe do IOF exige ser saída de algum MeasurementProcess (planejado), o que o sensoriamento contínuo não é (ODR-009 §4 superseded). Mesmo padrão describes / expressão de valor. É o conteúdo que distingue um instrumento de medição (COPI_0000024) de um instrumento qualquer.",
  rat_en="Primitive: the describes/value-expression pattern is necessary; sufficiency would require 'produced by sensing', a provenance condition COPI records on the signal flow, not on the content.",
  rat_pt="Primitiva: o padrão describes/expressão de valor é necessário; a suficiência exigiria 'produzido por sensoriamento', uma condição de proveniência que a COPI registra no fluxo de sinal, não no conteúdo.",
  sources=["ODR-024 §6", "ODR-023 (reading A)", IOF + ": MeasurementInformationContentEntity, hasValueExpressionAtAllTimes, MeasuredValueExpression", ISA51], adapted=IOF + ": MeasurementInformationContentEntity (close match)")
A("ControlContent",
  nld_pt="entidade de conteúdo de informação diretiva que prescreve uma qualidade do artefato acionado (uma abertura de válvula, uma rotação de bomba)",
  sfd_en="if c is a 'control content' then c is a 'directive information content entity' that 'prescribes' some 'quality'",
  sfd_pt="se c é um 'conteúdo de controle' então c é uma 'entidade de conteúdo de informação diretiva' que 'prescreve' alguma 'qualidade'",
  fol="∀c (ControlContent(c) → DirectiveInformationContentEntity(c) ∧ ∃q (Quality(q) ∧ prescribes(c,q)))",
  ex_en="The setpoint sent to a control valve positioner; the speed command to a variable-speed drive; an interlock command closing an ESD valve.",
  ex_pt="O setpoint enviado ao posicionador de uma válvula de controle; o comando de rotação a um inversor; um comando de intertravamento fechando uma válvula ESD.",
  note_pt="Conteúdos de intertravamento e de trip são conteúdos de controle. A qualidade-alvo (abertura, rotação) é a que a função de regulação ou atuação do artefato acionado altera.",
  rat_en="Primitive: 'prescribes some quality' is necessary; the IOF directive ICE is itself primitive.",
  rat_pt="Primitiva: 'prescreve alguma qualidade' é necessário; a ICE diretiva do IOF é ela mesma primitiva.",
  sources=["ODR-024 §6", IOF + ": DirectiveInformationContentEntity, prescribes", ISA51], adapted=IOF)
A("StatusContent",
  nld_pt="entidade de conteúdo de informação descritiva cujo conteúdo é discreto: que uma qualidade cruzou um limite (nível alto, chama detectada) ou a condição de um artefato (bomba em operação)",
  sfd_en="if c is a 'status content' then c is a 'descriptive information content entity' that 'describes' some 'quality' and whose content is discrete",
  sfd_pt="se c é um 'conteúdo de estado' então c é uma 'entidade de conteúdo de informação descritiva' que 'descreve' alguma 'qualidade' e cujo conteúdo é discreto",
  fol="∀c (StatusContent(c) → DescriptiveInformationContentEntity(c) ∧ ∃q (Quality(q) ∧ describes(c,q)))",
  ex_en="A high-level alarm; the flame-detected status of a burner; the running/stopped status of a pump.",
  ex_pt="Um alarme de nível alto; o estado chama-detectada de um queimador; o estado operando/parada de uma bomba.",
  note_pt="Alarmes são conteúdos de estado com referência a um limite. Chaves e detectores produzem conteúdo de estado. Evidência: na cobertura, as oito chaves e detectores oscilaram entre medição e controle por falta de lugar para 'cruzou o limite'. Um quarto tipo só se uma CQ exigir distinguir alarme de evento (ISA-18.2).",
  rat_en="Primitive: 'discrete' is a property of the value expression, stated in natural language; it does not separate status from measurement content formally.",
  rat_pt="Primitiva: 'discreto' é uma propriedade da expressão de valor, dita em linguagem natural; não separa formalmente conteúdo de estado de conteúdo de medição.",
  sources=["ODR-024 §6", IOF + ": DescriptiveInformationContentEntity", ISA51, "ANSI/ISA-18.2 Management of Alarm Systems"], adapted=IOF)
